import{_ as i,o as a,c as e,a2 as l}from"./chunks/framework.CZqXuAiL.js";const c=JSON.parse('{"title":"CLI Reference","description":"Firewall-Plus artisan commands (firewall-plus:*) and node-service scripts.","frontmatter":{"title":"CLI Reference","description":"Firewall-Plus artisan commands (firewall-plus:*) and node-service scripts."},"headers":[],"relativePath":"firewall-plus/fwp-aside/user-guide/cli.md","filePath":"firewall-plus/fwp-aside/user-guide/cli.md","lastUpdated":null}'),t={name:"firewall-plus/fwp-aside/user-guide/cli.md"};function n(p,s,h,r,d,o){return a(),e("div",null,[...s[0]||(s[0]=[l('<h1 id="cli-reference" tabindex="-1">CLI Reference <a class="header-anchor" href="#cli-reference" aria-label="Permalink to &quot;CLI Reference&quot;">​</a></h1><h2 id="artisan-commands-panel" tabindex="-1">Artisan Commands (panel) <a class="header-anchor" href="#artisan-commands-panel" aria-label="Permalink to &quot;Artisan Commands (panel)&quot;">​</a></h2><p>Run from the panel directory (<code>cd /var/www/pterodactyl</code>). All commands are registered by the Firewall-Plus service provider.</p><h3 id="firewall-plus-sync-nodes" tabindex="-1"><code>firewall-plus:sync-nodes</code> <a class="header-anchor" href="#firewall-plus-sync-nodes" aria-label="Permalink to &quot;`firewall-plus:sync-nodes`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:sync-nodes</span></span></code></pre></div><p>Health-checks every registered node (ONLINE/OFFLINE badge, reported version, GeoIP availability). <strong>Runs every minute via the scheduler.</strong> When a node returns to ONLINE, a reconcile is dispatched automatically.</p><h3 id="firewall-plus-reconcile" tabindex="-1"><code>firewall-plus:reconcile</code> <a class="header-anchor" href="#firewall-plus-reconcile" aria-label="Permalink to &quot;`firewall-plus:reconcile`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:reconcile</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:reconcile</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --node=3</span></span></code></pre></div><p>Compares desired state (panel DB) against node state and repairs drift. Runs every 15 minutes scheduled; use <code>--node=</code> to reconcile a single node after manual intervention.</p><h3 id="firewall-plus-cleanup-orphans" tabindex="-1"><code>firewall-plus:cleanup-orphans</code> <a class="header-anchor" href="#firewall-plus-cleanup-orphans" aria-label="Permalink to &quot;`firewall-plus:cleanup-orphans`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:cleanup-orphans</span></span></code></pre></div><p>Removes orphaned profiles/rules — servers deleted or transferred while their node was offline. Runs every 30 minutes scheduled.</p><h3 id="firewall-plus-sync-integrity" tabindex="-1"><code>firewall-plus:sync-integrity</code> <a class="header-anchor" href="#firewall-plus-sync-integrity" aria-label="Permalink to &quot;`firewall-plus:sync-integrity`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:sync-integrity</span></span></code></pre></div><p>Verifies sync-state integrity across profiles (<code>pending → syncing → synced / failed / orphaned</code>) and repairs inconsistent rows.</p><h3 id="firewall-plus-process-cleanups" tabindex="-1"><code>firewall-plus:process-cleanups</code> <a class="header-anchor" href="#firewall-plus-process-cleanups" aria-label="Permalink to &quot;`firewall-plus:process-cleanups`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:process-cleanups</span></span></code></pre></div><p>Processes pending cleanup tasks queued by lifecycle events (server deletion, node transfer, allocation changes). Visible in <strong>Admin → Firewall → Operations</strong>.</p><h3 id="firewall-plus-emergency-flush" tabindex="-1"><code>firewall-plus:emergency-flush</code> <a class="header-anchor" href="#firewall-plus-emergency-flush" aria-label="Permalink to &quot;`firewall-plus:emergency-flush`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:emergency-flush</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --all-nodes</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --confirm</span></span></code></pre></div><p>Flushes <strong>all</strong> Firewall-Plus chains and ipsets on all online nodes. Requires <code>--confirm</code>. This is the big red button — pair it with Emergency mode (below) so users don&#39;t immediately re-queue applies.</p><h3 id="firewall-plus-prune-audit-logs" tabindex="-1"><code>firewall-plus:prune-audit-logs</code> <a class="header-anchor" href="#firewall-plus-prune-audit-logs" aria-label="Permalink to &quot;`firewall-plus:prune-audit-logs`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:prune-audit-logs</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:prune-audit-logs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days=60</span></span></code></pre></div><p>Deletes audit log entries older than the retention window (default 90 days, configurable via the <code>audit_retention_days</code> admin setting). Runs daily at 03:15 scheduled.</p><h3 id="firewall-plus-prune-queue" tabindex="-1"><code>firewall-plus:prune-queue</code> <a class="header-anchor" href="#firewall-plus-prune-queue" aria-label="Permalink to &quot;`firewall-plus:prune-queue`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:prune-queue</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus:prune-queue</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --days=14</span></span></code></pre></div><p>Deletes firewall queue entries older than N days (default 7) — keeps <code>firewall_queue_entries</code> from growing unbounded on busy panels. Stuck entries are also reset automatically by the <code>ResetStuckFirewallQueueJob</code>.</p><hr><h2 id="scheduler-overview" tabindex="-1">Scheduler Overview <a class="header-anchor" href="#scheduler-overview" aria-label="Permalink to &quot;Scheduler Overview&quot;">​</a></h2><p>Requires the standard panel cron: <code>* * * * * php /var/www/pterodactyl/artisan schedule:run</code>.</p><table tabindex="0"><thead><tr><th>Interval</th><th>Job / Command</th></tr></thead><tbody><tr><td>Every minute</td><td><code>firewall-plus:sync-nodes</code></td></tr><tr><td>Every 2 minutes</td><td><code>SyncSmartEventsJob</code> (node SMART events → panel)</td></tr><tr><td>Every 15 minutes</td><td><code>firewall-plus:reconcile</code></td></tr><tr><td>Every 30 minutes</td><td><code>firewall-plus:cleanup-orphans</code></td></tr><tr><td>Daily 03:15</td><td><code>firewall-plus:prune-audit-logs</code></td></tr></tbody></table><p>Applies themselves are queue jobs (<code>ApplyFirewallRulesJob</code>) — you also need a queue worker (<code>pteroq</code> service or <code>php artisan queue:work</code>).</p><hr><h2 id="emergency-operations" tabindex="-1">Emergency Operations <a class="header-anchor" href="#emergency-operations" aria-label="Permalink to &quot;Emergency Operations&quot;">​</a></h2><p>The full incident procedure, available from <strong>Admin → Firewall → Emergency</strong> or the CLI:</p><ol><li><strong>Freeze user changes</strong> — enable <strong>Emergency mode</strong> (admin UI, or set <code>firewall_admin_settings.emergency_mode = 1</code>). All client mutations and queued applies are blocked while it&#39;s on.</li><li><strong>Flush everything</strong> — emergency flush button or <code>php artisan firewall-plus:emergency-flush --all-nodes --confirm</code>.</li><li><strong>Surgical option</strong> — disable specific rule types fleet-wide from the Emergency page instead of a full flush.</li><li><strong>Fleet lockdown (optional)</strong> — disable Firewall fleet access to block API mutations until re-enabled.</li></ol><p>Verify nodes are clean afterward:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iptables-nft</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> 2&gt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">/dev/null</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FWP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FWP</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;no FWP chains&quot;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">ipset</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> list</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fwp</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> ||</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> echo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &quot;no fwp ipsets&quot;</span></span></code></pre></div><hr><h2 id="node-scripts" tabindex="-1">Node Scripts <a class="header-anchor" href="#node-scripts" aria-label="Permalink to &quot;Node Scripts&quot;">​</a></h2><p>Shipped in <code>node-service/scripts/</code> — run on the Wings host.</p><h3 id="diagnose-fwp-sh" tabindex="-1"><code>diagnose-fwp.sh</code> <a class="header-anchor" href="#diagnose-fwp-sh" aria-label="Permalink to &quot;`diagnose-fwp.sh`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sudo</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> bash</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> /opt/firewall-plus/scripts/diagnose-fwp.sh</span></span></code></pre></div><p>Collects a diagnostic bundle: service status, recent journal, detected iptables binaries, FWP chain/ipset presence, config sanity. First thing to run (and attach) when applies misbehave.</p><h3 id="test-queue-mjs" tabindex="-1"><code>test-queue.mjs</code> <a class="header-anchor" href="#test-queue-mjs" aria-label="Permalink to &quot;`test-queue.mjs`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FWP_SKIP_IPTABLES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FWP_TEST_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">64-hex</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/test-queue.mjs</span></span></code></pre></div><p>Smoke-tests the node apply queue end-to-end without touching iptables.</p><h3 id="load-test-apply-mjs" tabindex="-1"><code>load-test-apply.mjs</code> <a class="header-anchor" href="#load-test-apply-mjs" aria-label="Permalink to &quot;`load-test-apply.mjs`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">export</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FWP_SKIP_IPTABLES</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> FWP_TEST_TOKEN</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">64-hex</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/load-test-apply.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --concurrency</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 100</span></span></code></pre></div><p>Hammers the apply endpoint with concurrent requests — validates queue backpressure and rate limiting. Target: the queue accepts all applies without errors.</p><h3 id="soak-monitor-mjs" tabindex="-1"><code>soak-monitor.mjs</code> <a class="header-anchor" href="#soak-monitor-mjs" aria-label="Permalink to &quot;`soak-monitor.mjs`&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">node</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> scripts/soak-monitor.mjs</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --hours</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 1</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --interval</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 60</span></span></code></pre></div><p>Watches daemon memory/health over time. Target: RSS stable under 100 MB over a 72h soak.</p><hr><h2 id="useful-one-liners" tabindex="-1">Useful One-Liners <a class="header-anchor" href="#useful-one-liners" aria-label="Permalink to &quot;Useful One-Liners&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Trace a single apply across the node by correlation ID</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">journalctl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> firewall-plus</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> grep</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;&lt;correlation-uuid&gt;&#39;</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Live rules for one server</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">iptables</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -L</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> FWP-</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">serverI</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -v</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Which iptables backend the daemon would use</span></span>\n<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables-nft</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> iptables-nft-restore</span></span>\n<span class="line"></span>\n<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;"># Node version + jump style (detect version skew)</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">curl</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -s</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> http://127.0.0.1:8472/api/v1/health</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> |</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> jq</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;{version: .meta.version, input_jump_style: .data.input_jump_style}&#39;</span></span></code></pre></div>',56)])])}const u=i(t,[["render",n]]);export{c as __pageData,u as default};
